import { cp, mkdir, readdir, unlink } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const dist = new URL('dist/', root);
for (const path of ['projects.html', 'about.html', 'contact.html', 'styles.css', 'projects.json', 'projects', 'assets', 'favicon.ico', 'mewebkg.png']) {
  await cp(new URL(path, root), new URL(path, dist), { recursive: true });
}
const generated = new URL('archive-assets/', root);
await mkdir(generated, { recursive: true });
// Remove only files generated by this build; legacy assets/ is never touched.
for (const name of await readdir(generated)) {
  if (/^.+-[\w-]+\.(js|css)$/.test(name)) await unlink(new URL(name, generated));
}
await cp(new URL('archive-assets/', dist), generated, { recursive: true });
await cp(new URL('index.html', dist), new URL('index.html', root));
console.log('Packaged dist/ and synchronized the root homepage for buildless hosting.');
